const mode = String($env.WEBHOOK_VERIFY_SIGNATURE || 'false').toLowerCase();
const passthrough = (verified, m) => [{ json: Object.assign({ verified, mode: m }, $input.first().json) }];
if (mode === 'false') { return passthrough(true, 'disabled'); }
const secret = $env.META_APP_SECRET || '';
const headers = $input.first().json.headers || {};
const signature = headers['x-hub-signature-256'] || headers['X-Hub-Signature-256'] || '';
const rawBody = JSON.stringify($input.first().json.body);
if (!secret) { return passthrough(false, 'missing_secret'); }
const run = async () => { try { const encoder = new TextEncoder(); const key = await crypto.subtle.importKey('raw', encoder.encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']); const sig = await crypto.subtle.sign('HMAC', key, encoder.encode(rawBody)); const hex = Array.from(new Uint8Array(sig)).map(b => b.toString(16).padStart(2, '0')).join(''); return passthrough(signature === 'sha256=' + hex, 'enabled'); } catch (e) { return passthrough(false, 'crypto_unavailable'); } };
return run();

// Normaliza el payload; los eventos no-mensaje (status, tipos raros, propio negocio) terminan en silencio (return []).
const payload = $input.first().json;
const businessPhone = ($env.WHATSAPP_BUSINESS_PHONE || '').replace(/\D/g, '');
for (const entry of payload.body.entry || payload.entry || []) {
  for (const change of entry.changes || []) {
    const value = change.value || {};
    if (value.messages && value.messages.length > 0) {
      const msg = value.messages[0];
      const from = String(msg.from || '').replace(/\D/g, '');
      if (businessPhone && from === businessPhone) { return []; }
      const hasText = msg.text && msg.text.body;
      if (msg.type && msg.type !== 'text' && !hasText) {
      const label = { image: '🖼️ [El cliente envio una imagen]', audio: '🎤 [El cliente envio un audio]', video: '🎬 [El cliente envio un video]', document: '📄 [El cliente envio un documento]' }[msg.type] || '📎 [El cliente envio un adjunto]';
      return [{ json: { valid: true, contact_phone: from, message_text: label, message_id: msg.id || '', timestamp: msg.timestamp || '', type: msg.type || 'media' } }];
    }
      if (!hasText) { return []; }
      return [{ json: { valid: true, contact_phone: from, message_text: String(msg.text.body).slice(0, 2000), message_id: msg.id || '', timestamp: msg.timestamp || '', type: msg.type || 'text' } }];
    }
    if (value.statuses && value.statuses.length > 0) { return []; }
  }
}
return [];

// Encuentra la fila del contacto en cualquier forma de respuesta (array, body, anidado).
const findRow = (x) => {
  if (Array.isArray(x)) { for (const it of x) { const f = findRow(it); if (f) return f; } return null; }
  if (x && typeof x === 'object') {
    if (x.id && (x.telefono || x.tenant_id)) return x;
    for (const v of Object.values(x)) { const f = findRow(v); if (f) return f; }
  }
  return null;
};
const row = findRow($json) || {};
if (!row.id) { throw new Error('UPSERT-FALLO: ' + JSON.stringify($json).slice(0, 300)); }
return [{ json: { contacto_id: row.id, tenant_id: row.tenant_id || null } }];

let historyRows = [];
try { historyRows = $('Obtener Historial').all().map(i => i.json).flat(1).filter(r => r && typeof r === 'object' && !Array.isArray(r)); } catch (e) {}
const historial = historyRows.slice(-10).map(h => ({ role: h.role === 'assistant' ? 'assistant' : 'user', content: h.content }));
const mensajeActual = $('Normalizar Mensaje').item.json.message_text;
const systemPrompt = `Eres el asistente virtual de JeanCRG, consultoria de software e inteligencia artificial en Colombia. Representas a Jean, un emprendedor colombiano que vende asistentes IA para WhatsApp, automatizaciones y desarrollo web.

PERSONALIDAD Y TONO:
- Cercano, respetuoso y con energia positiva, como un vendedor colombiano profesional.
- Emojis con moderacion (👋 😊 🚀 ✅ 📅 💬).
- Espanol neutro colombiano: "¿Que negocio tienes?", "claro", "perfecto". Usa "tu" (nunca "vos"), sin jerga extrema ni regionalismos cerrados.
- Formato WhatsApp: *negrita* para precios y nombres de servicios.
- Maximo 2-3 frases por mensaje. SIEMPRE termina con UNA pregunta (nunca dos).
- Nunca uses listas largas: si el cliente pregunta por todos los servicios, menciona los 3 principales y pregunta cual le llama la atencion.

REGLAS DE CONVERSACION:
1. Saludo: saludas y te presentas SOLO en la primera interaccion de la conversacion. Las siguientes veces respondes directo al tema, como un vendedor que ya saludo.
2. Si el cliente vuelve a saludar a mitad de conversacion ("hola", "buenas"), responde amable sin volver a presentarte: "¡Hola! ¿En que te ayudo?"
3. Si te preguntan si eres robot: "Soy el asistente virtual de JeanCRG 🤖 Respondo al instante y con informacion real del negocio. Si prefieres, te conecto con un asesor humano."
4. Objeciones de precio ("esta caro", "no tengo plata", "lo voy a pensar"): responde con empatia y ofrece el *Piloto de 15 dias por $800.000* (100% descontable) o el *Diagnostico tecnologico por $300.000* (descontable). Ejemplo: "Te entiendo 😊 Por eso tenemos el piloto de 15 dias por *$800.000*, 100% descontable del servicio final. ¿Te cuento como funciona?"
5. Agradecimientos y cierres ("gracias", "listo", "quedo claro"): responde calido y deja la puerta abierta: "¡Con gusto! 😊 Cuando quieras avanzamos. ¿Te comparto el enlace para agendar tu consulta gratis?" (solo si hay interes previo).
6. Preguntas fuera del tema: redirige amablemente a los servicios de JeanCRG.
7. Errores de tipeo, mensajes sin puntuacion o de voz: responde normal, sin corregir al cliente.
8. Si preguntan horarios o disponibilidad: sugiere agendar en https://calendly.com/jeancrg/consulta-gratuita con el caso exacto de agendamiento.

SERVICIOS EXACTOS (nunca inventes precios, servicios NI funciones: no menciones pasarelas de pago, cobros, apps ni nada que no este aqui):
1) *Asistente IA para WhatsApp* desde *$1.800.000* + retainer mensual de *$250.000* (montaje en 5 dias)
2) *Diagnostico tecnologico* por *$300.000* (descontable)
3) *Automatizaciones con n8n* desde *$1.500.000*
4) *Chatbot con datos propios (RAG)* desde *$2.500.000*
5) *Tienda online* desde *$2.500.000*
6) *Desarrollo a medida* desde *$3.000.000*
*Piloto de 15 dias por $800.000* (100% descontable del servicio final).

CASOS ESPECIFICOS (obligatorio, respuestas EXACTAS cuando aplique):
- PRIMERA interaccion con mensaje que ES solo un saludo simple (sin pregunta): '¡Hola! 👋 Soy el asistente de JeanCRG. Te ayudo con asistentes IA para WhatsApp, automatizaciones y desarrollo web. ¿Que negocio tienes?'
- PRIMERA interaccion que YA trae una pregunta o necesidad concreta (precio, servicio, problema del negocio): responde DIRECTAMENTE su pregunta con el precio y servicio exactos, y cierra preguntando por su negocio. NO repitas la presentacion completa.
- Conversacion ya iniciada: responde directo y natural al tema, sin saludos ni presentaciones (ejemplo: '¡Claro! El asistente IA para WhatsApp cuesta desde *$1.800.000* y lo dejamos montado en 5 dias. ¿Que negocio tienes?')
- Quiere agendar/cotizar/propuesta: tu respuesta DEBE ser EXACTAMENTE: '¡Perfecto! 📅 Te comparto el enlace para que elijas el horario que prefieras: https://calendly.com/jeancrg/consulta-gratuita ¿Te queda mejor por la manana o por la tarde?' y agrega [LEAD cita] al final. PROHIBIDO pedir dia u hora, PROHIBIDO confirmar horarios, PROHIBIDO mencionar otros servicios en esa respuesta.
- Pide hablar con un humano o esta frustrado/insatisfecho: tu respuesta DEBE ser EXACTAMENTE: 'Entendido 👤 Un asesor te escribe por este chat en unos minutos. ¿Me confirmas tu nombre para que te atienda con tu caso?' y agrega [DERIVAR] al final. PROHIBIDO seguir vendiendo o pedir mas datos.`;
const fechaBogota = new Date().toLocaleString('es-CO', { timeZone: 'America/Bogota', weekday: 'long', day: 'numeric', month: 'long', year: 'numeric', hour: '2-digit', minute: '2-digit', hour12: true });
let notaTiempo = '';
try {
  const ordenadas = historyRows.slice().sort((a, b) => String(a.created_at || '').localeCompare(String(b.created_at || '')));
  const ultimaTs = ordenadas.length ? ordenadas[ordenadas.length - 1].created_at : null;
  if (ultimaTs) {
    const horas = (Date.now() - new Date(ultimaTs).getTime()) / 3600000;
    if (horas >= 72) notaTiempo = '\n\nCONTEXTO TEMPORAL IMPORTANTE: Han pasado ' + Math.round(horas / 24) + ' DIAS desde el ultimo mensaje del cliente. Empieza reconociendo la ausencia con UNA frase corta y calida (ej: \u00a1Que bueno saber de ti otra vez!) y SOLO DESPUES retoma el tema.';
    else if (horas >= 20) notaTiempo = '\n\nCONTEXTO TEMPORAL: Ha pasado mas de un dia desde el ultimo mensaje del cliente.';
    else notaTiempo = '\n\nCONTEXTO TEMPORAL: Conversacion activa hoy mismo.';
  }
} catch (e) {}
const sysContent = 'FECHA Y HORA ACTUAL EN COLOMBIA: ' + fechaBogota + '. Usa esta referencia para palabras como hoy, manana o dias de la semana. Nunca inventes fechas.\n\n' + systemPrompt + notaTiempo;
const messages = [{ role: 'system', content: sysContent }].concat(historial).concat([{ role: 'user', content: mensajeActual }]);
return [{ json: { model: 'mimo-v2.5', thinking: { type: 'disabled' }, messages } }];

const text = (($json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content) || '');
const cleanRaw = text.replace(/\[DERIVAR\]/gi, '').replace(/\[LEAD[^\]]*\]/gi, '').trim().slice(0, 4000);
const userText = ($('Normalizar Mensaje').item.json.message_text || '').toLowerCase();
const rows = (() => { try { return $('Obtener Historial').all().map(i => i.json).flat(1).filter(r => r && typeof r === 'object' && !Array.isArray(r)); } catch (e) { return [1]; } })();
const primerMensaje = !/(cuesta|precio|ayuda|quien|servicio|agenda|pago|pedido|compra|negocio|tienda|vende|vender|gracias|listo)/i.test(userText);
const esSaludo = /^(hola|holi|buenas|buen dia|buenos dias|buenas tardes|buenas noches|hi|hello|ey|hey|oie|q mas|que mas|qu[eé] mas)[\s!¡?¿.,]*(raza|bebe)?\s*$/i.test(userText) && primerMensaje;
// SALUDO (primera vez o de vuelta): respuesta EXACTA fija, sin IA ni marcadores
if (esSaludo) {
  const txt = rows.length === 0
    ? '¡Hola! 👋 Soy el asistente de JeanCRG. Te ayudo con asistentes IA para WhatsApp, automatizaciones y desarrollo web. ¿Qué negocio tienes?'
    : '¡Hola! 😊 ¿En qué te ayudo?';
  return [{ json: { raw: text, clean: txt, needs_human: false, lead_marker: '', evento: 'none', determinista: true } }];
}
const HUMAN_RE = /(hablar con (alguien|un humano|una persona|un asesor|alguien real)|asesor humano|persona real|no me convence|no me gusta|queja|quejarme|molest|frustrad|insatisfech|ineficiente|mal servicio|estafa|representante|me canse|aburrid|quien me atiende|hay alguien|atendeme|quiero a alguien|llamen|llamame)/i;
const LEAD_RE = /(agendar|cita|reuni[oó]n|diagn[oó]stic|cotiz|propuest|presupuest|quiero (comprar|contratar|empezar)|me interesa|cu[áa]nto cuesta|cu[áa]nto vale|precio|precios|valor|tarifa|demo|prueba|pruebo|piloto|m[áa]s informaci[oó]n|me cuentas|c[oó]mo funciona|en cu[áa]nto|ayudame con)/i;
const OBJ_RE = /(caro|carita|cara|costoso|no me alcanza|no tengo plata|lo pienso|lo voy a pensar|demasiado|no me sobra|presupuesto apretado|ya tengo otro|lo consulto)/i;
const PEDIDO_RE = /(pedido|quiero (pedir|ordenar|encargar|reservar)|me llevo|hacer (un|mi) pedido|domicilio|delivery|a domicilio|talla|disponibilidad)/i;
const PAGO_RE = /(pagar|pago|transferenc|nequi|daviplata|davi|tarjeta|bono|cup[oó]n|promoci[oó]n|adelanto|consignaci[oó]n)/i;
const marker = (text.match(/\[LEAD ([^\]]*)\]/i) || [null, ''])[1];
const aiDeriva = /\[DERIVAR\]/i.test(text);
// DERIVAR solo si el USUARIO pide humano; el [DERIVAR] de la IA solo cuenta si ademas el usuario habla de asesor/humano/persona/llamada
let evento = 'none';
if (HUMAN_RE.test(userText) || (aiDeriva && /(asesor|humano|persona|hablar|llamad)/i.test(userText))) evento = 'derivar';
else if (marker || LEAD_RE.test(userText)) evento = 'lead';
else if (OBJ_RE.test(userText)) evento = 'objecion';
else if (PAGO_RE.test(userText)) evento = 'pago';
else if (PEDIDO_RE.test(userText)) evento = 'pedido';
// si la IA alucino [DERIVAR] sin senal del usuario, usar su texto limpio normal
return [{ json: { raw: text, clean: cleanRaw, needs_human: evento === 'derivar', lead_marker: marker || (LEAD_RE.test(userText) ? 'cita' : ''), evento } }];

// Emite es_lead + datos; sin throw (el insert se hace no-op con body [] cuando no hay lead).
const lead = $('Extraer Respuesta').item.json.lead_marker || '';
const parts = lead ? String(lead).split('|') : [];
return [{ json: {
  es_lead: Boolean(lead),
  nombre: (parts[0] || '').trim(),
  telefono: $('Normalizar Mensaje').item.json.contact_phone,
  interes: (parts[2] || parts[0] || '').trim()
} }];

const extra = $('Extraer Respuesta').item.json;
const phone = $('Normalizar Mensaje').item.json.contact_phone;
const evento = extra.evento || 'none';
const emojis = { derivar: '🚨 DERIVAR', lead: '📅 LEAD', objecion: '⚡ OBJECIÓN', pedido: '🛒 PEDIDO', pago: '💰 PAGO' };
const notificar = evento !== 'none';
const texto = notificar ? (emojis[evento] + ': ' + phone + ' | ' + extra.clean) : '';
return [{ json: { notificar, texto } }];
